<?php require 'includes/auth.php'; if($_SERVER['REQUEST_METHOD']==='POST'){ $s=$pdo->prepare("SELECT * FROM users WHERE email=?");$s->execute([$_POST['email']]);$u=$s->fetch();if($u&&password_verify($_POST['password'],$u['password'])){$_SESSION['uid']=$u['id'];header('Location: '.($u['role']==='admin'?'admin/':'account.php'));exit;}$err='Email atau password salah.';} ?><!doctype html><html lang=id><head><meta charset=utf-8><meta name=viewport content="width=device-width,initial-scale=1"><link rel=stylesheet href=assets/style.css><title>Masuk</title></head><body><main class=checkout><h1>Masuk HK PRINTING</h1><?php if(isset($err))echo '<p class=err>'.e($err).'</p>';?><form method=post><input type=email name=email required placeholder="Email"><input type=password name=password required placeholder="Password"><button class=btn>Masuk</button></form><p>Belum punya akun? <a href=register.php>Daftar</a></p></main></body></html>
